import{_ as i,a0 as s,w as l,s as m,I as n,x as e,a1 as p,A as r,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse(`{"title":"Linux 的 'sort'命令的七个有趣实例（二） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 的 'sort'命令的七个有趣实例（二） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 的 'sort'命令的七个有趣实例（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 的 'sort'命令的七个有趣实例（二） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150420 7 Interesting Linux 'sort' Command Examples--Part 2","title":"Linux 的 'sort'命令的七个有趣实例（二）","tag":"201505","desc":""},"relativePath":"201505/20150420 7 Interesting Linux 'sort' Command Examples--Part 2.md","filePath":"[post].md"}`),d={name:"201505/20150420 7 Interesting Linux 'sort' Command Examples--Part 2.md"};function c(u,t,w,x,f,g){const o=s("Link");return l(),m("div",null,[t[17]||(t[17]=n("h1",{id:"linux-的-sort-命令的七个有趣实例-二",tabindex:"-1"},[e("Linux 的 'sort'命令的七个有趣实例（二） "),n("a",{class:"header-anchor",href:"#linux-的-sort-命令的七个有趣实例-二","aria-label":"Permalink to “Linux 的 'sort'命令的七个有趣实例（二）”"},"​")],-1)),n("p",null,[t[1]||(t[1]=e("在",-1)),p(o,{href:"http://www.tecmint.com/sort-command-linux/"},{default:r(()=>[...t[0]||(t[0]=[e("上一篇文章",-1)])]),_:1}),t[2]||(t[2]=e("里，我们已经探讨了关于sort命令的多个例子，如果你错过了这篇文章，可以点击下面的链接进行阅读。今天的这篇文章作为上一篇文章的继续，将讨论关于sort命令的剩余用法，与上一篇一起作为Linux ‘sort’命令的完整指南。",-1))]),n("ul",null,[n("li",null,[p(o,{href:"http://www.tecmint.com/sort-command-linux/"},{default:r(()=>[...t[3]||(t[3]=[e("Linux 的 ‘sort’命令的14个有用的范例（一）",-1)])]),_:1})])]),t[18]||(t[18]=a(`<p>在我们继续深入之前，先创建一个文本文档‘month.txt’，并且将上一次给出的数据填进去。</p><pre><code>$ echo -e &quot;mar\\ndec\\noct\\nsep\\nfeb\\naug&quot; &gt; month.txt
$ cat month.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Content.gif" alt="Populate Content"></p><p>15、 通过使用’M‘选项，对’month.txt‘文件按照月份顺序进行排序。</p><pre><code>$ sort -M month.txt
</code></pre><p><strong>注意</strong>:‘sort’命令需要至少3个字符来确认月份名称。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-by-Month.gif" alt="Sort File Content by Month in Linux"></p><p>16、 把数据整理成方便人们阅读的形式，比如1K、2M、3G、2T，这里面的K、G、M、T代表千、兆、吉、梯。 （LCTT 译注：此处命令有误，ls 命令应该增加 -h 参数，径改之）</p><pre><code>$ ls -lh /home/$USER | sort -h -k5
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-Human-Readable-Format.gif" alt="Sort Content Human Readable Format"></p><p>17、 在上一篇文章中，我们在例子4中创建了一个名为‘sorted.txt’的文件，在例子6中创建了一个‘lsl.txt’。‘sorted.txt&#39;已经排好序了而’lsl.txt‘还没有。让我们使用sort命令来检查两个文件是否已经排好序。</p><pre><code>$ sort -c sorted.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-File-is-Sorted.gif" alt="Check File is Sorted"></p><p>如果它返回0，则表示文件已经排好序。</p><pre><code>$ sort -c lsl.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-File-Sorted-Status.gif" alt="Check File Sorted Status"></p><p>报告无序。存在矛盾……</p><p>18、 如果文字之间的分隔符是空格，sort命令自动地将空格后的东西当做一个新文字单元，如果分隔符不是空格呢？</p><p>考虑这样一个文本文件，里面的内容可以由除了空格之外的任何符号分隔，比如‘|’，‘\\’，‘+’，‘.’等……</p><p>创建一个分隔符为+的文本文件。使用‘cat‘命令查看文件内容。</p><pre><code>$ echo -e &quot;21+linux+server+production\\n11+debian+RedHat+CentOS\\n131+Apache+Mysql+PHP\\n7+Shell Scripting+python+perl\\n111+postfix+exim+sendmail&quot; &gt; delimiter.txt
</code></pre><hr><pre><code>$ cat delimiter.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-File-Content.gif" alt="Check File Content by Delimiter"></p><p>现在基于由数字组成的第一个域来进行排序。</p><pre><code>$ sort -t &#39;+&#39; -nk1 delimiter.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-File-By-Fields.gif" alt="Sort File By Fields"></p><p>然后再基于非数字的第四个域排序。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Non-Numeric.gif" alt="Sort Content By Non Numeric"></p><p>如果分隔符是制表符，你需要在’+‘的位置上用$’\\t’代替，如上例所示。</p><p>19、 对主用户目录下使用‘ls -l’命令得到的结果基于第五列（‘文件大小’）进行一个乱序排列。</p><pre><code>$ ls -l /home/avi/ | sort -k5 -R 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-by-Column1.gif" alt="Sort Content by Column in Random Order"></p><p>每一次你运行上面的脚本，你得到结果可能都不一样，因为结果是随机生成的。</p><p>正如我在上一篇文章中提到的规则2所说——sort命令会将以小写字母开始的行排在大写字母开始的行前面。看一下上一篇文章的例3，字符串‘laptop’在‘LAPTOP’前出现。</p><p>20、 如何覆盖默认的排序优先权？在这之前我们需要先将环境变量LC_ALL的值设置为C。在命令行提示栏中运行下面的代码。</p><pre><code>$ export LC_ALL=C
</code></pre><p>然后以非默认优先权的方式对‘tecmint.txt’文件重新排序。</p><pre><code>$ sort tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Override-Sorting-Preferences.gif" alt="Override Sorting Preferences"></p><p><em>覆盖排序优先权</em></p><p>不要忘记与example 3中得到的输出结果做比较，并且你可以使用‘-f’，又叫‘-ignore-case’（忽略大小写）的选项来获取更有序的输出。</p><pre><code>$ sort -f tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Compare-Sorting-Preferences.gif" alt="Compare Sorting Preferences"></p><p>21、 给两个输入文件进行‘sort‘，然后把它们连接成一行！</p><p>我们创建两个文本文档’file1.txt‘以及’file2.txt‘，并用数据填充，如下所示，并用’cat‘命令查看文件的内容。</p><pre><code>$ echo -e “5 Reliable\\n2 Fast\\n3 Secure\\n1 open-source\\n4 customizable” &gt; file1.txt
$ cat file1.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Content-with-Number.gif" alt="Populate Content with Numbers"></p><p>用如下数据填充’file2.txt‘。</p><pre><code>$ echo -e “3 RedHat\\n1 Debian\\n5 Ubuntu\\n2 Kali\\n4 Fedora” &gt; file2.txt
$ cat file2.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-File-with-Data.gif" alt="Populate File with Data"></p><p>现在我们对两个文件进行排序并连接。</p><pre><code>$ join &lt;(sort -n file1.txt) &lt;(sort file2.txt)
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Join-Two-Files.gif" alt="Sort Join Two Files"></p><p>我所要讲的全部内容就在这里了，希望与各位保持联系，也希望各位经常来逛逛。有反馈就在下面评论吧。</p><hr>`,56)),n("p",null,[t[5]||(t[5]=e("via: ",-1)),p(o,{href:"http://www.tecmint.com/linux-sort-command-examples/"},{default:r(()=>[...t[4]||(t[4]=[e("http://www.tecmint.com/linux-sort-command-examples/",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=e("作者：",-1)),p(o,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...t[6]||(t[6]=[e("Avishek Kumar",-1)])]),_:1}),t[10]||(t[10]=e(" 译者：",-1)),p(o,{href:"https://github.com/DongShuaike"},{default:r(()=>[...t[7]||(t[7]=[e("DongShuaike",-1)])]),_:1}),t[11]||(t[11]=e(" 校对：",-1)),p(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原创翻译，",-1)),p(o,{href:"http://linux.cn/"},{default:r(()=>[...t[13]||(t[13]=[e("Linux中国",-1)])]),_:1}),t[16]||(t[16]=e(" 荣誉推出",-1))])])}const L=i(d,[["render",c]]);export{S as __pageData,L as default};
